body_md:
\label{prop:sphere_backprojection}
Consider $\mathcal{M} = S^{d-1}(b,r)$ the sphere geometry defined in Section~\ref{sec:shift-sphere-geom}. Let $z \in \mathcal{M}$ and $v \in T_z\mathcal{M}$ satisfy $\|v\|<r$. Then:
\begin{enumerate}
\item[(i)] The projection scalar is $\alpha = -r + \sqrt{r^2 - \|v\|^2}$, and the proposed point is $z' = b + v + \sqrt{r^2 - \|v\|^2}\,\hat{n}$.

\item[(ii)] The new unit normal is $\hat{n}' = (z'-b)/r = (1 + \alpha/r)\,\hat{n} + v/r$.

\item[(iii)] The reverse tangent increment is $v' = -v - \alpha(\hat{n} + \hat{n}')$, and $\|v'\| = \|v\|$.
\end{enumerate}

\label{prop:Rc_sphere}
Under the notation above,
\begin{align}
  \langle v',b\rangle - \langle v,b\rangle
  &= -\bigl(2 + \alpha/r\bigr)\,g,
  \label{eq:vb_diff} \\
  \|P_{z'}(b)\|^2 - \|P_z(b)\|^2
  &= -\frac{2\langle \hat{n},b\rangle}{r}\,g - \frac{g^2}{r^2}.
  \label{eq:Pb_diff}
\end{align}
Consequently, the exact Metropolis defect of the proposal \eqref{eq:general_proposal} is
\begin{equation}
  R =
  \left(-1-\frac{2c}{\sigma^2} -\frac{c}{\sigma^2}\,\frac{\alpha}{r}
    +\frac{c^2}{\sigma^2}\,\frac{\langle\hat{n},b\rangle}{r} \right) g +
  \frac{c^2}{2\sigma^2}\,\frac{g^2}{r^2}.
  \label{eq:Rcancel_general}
\end{equation}
In particular, for tangent pCN
\begin{equation}
    R=
    \left( \frac{1-\rho}{1+\rho} + \frac{\alpha}{(1+\rho)r} \right) g + 
    \frac{1-\rho}{1+\rho}\left(  \frac{\langle \hat{n},b\rangle}{r}\,g + \frac{g^2}{2r^2} \right).
  \label{eq:Rcancel_exact}
\end{equation}

\label{lem:concentration_t}
For fixed $\delta,\kappa>0$, let $t \in[-1,1]$ have density \eqref{eq:t_density}. Set
\begin{equation*}
  t^*:=\frac{1-\sqrt{1+4\delta^2\kappa^2}}{2\delta\kappa}\in(-1,0),
  \qquad
  \sigma_{t^*}^2:=\frac{(1-(t^*)^2)^2}{1+(t^*)^2}.
\end{equation*}
Then
\begin{equation}
  \label{eq:t_CLT}
  \sqrt d\,(t-t^*)\xrightarrow{\makebox[1em][c]{$\scriptstyled$}}\mathcal N(0,\sigma_{t^*}^2).
\end{equation}
Moreover, for every $k\ge1$,
\begin{equation}
  \label{eq:t_moments}
  \mathbb{E}_\pi\bigl[|t-t^*|^k\bigr]=O(d^{-k/2}).
\end{equation}

\label{lem:g_cancellation}
Under stationarity on the shifted sphere, for $\beta=\beta_d\to0$,
\begin{equation}
  g = \beta\tau\sqrt d\,\xi_1
    + \Lambda\beta^4 d
    + O_p(\beta)
    + O_p(\beta^2\sqrt d)
    + O_p(\beta^3\sqrt d)
    + O(\beta^6 d)\,,
  \label{eq:g_final_clean}
\end{equation}
where $\Lambda := \tfrac18\tau^2 (s-1)$.
In particular, if $\beta^3\sqrt d=O(1)$, then
\begin{equation}
  g=O_p(\beta\sqrt d).
  \label{eq:g_order_statement}
\end{equation}

The definitions of $t^*$, $\tau$ and $s$ give
\begin{equation}
C_*=0\quad\Longleftrightarrow\quad s=1 \quad\Longleftrightarrow\quad \kappa^2=1+\delta^2.
\end{equation}
The $d^{-1/6}$ scaling results below assume $C_*\ne0$. On the exceptional curve, the intrinsic precision $\theta=s$ of Section~\ref{sec:geom-aware-corr} equals one, so the intrinsic proposal coincides with standard tangent pCN. Theorem~\ref{thm:fixed_step}(i) then gives a nondegenerate limiting stationary acceptance probability for every fixed $\beta\in(0,1)$.

\label{thm:gaussian_limit}
Assume $C_*\neq 0$, and let $\beta=\ell d^{-1/6}$ with $\ell>0$ fixed. Define
\begin{equation}
  \sigma_\ell := |C_*|\,\tau\,\ell^3.
\label{eq:sigmaell_def}
\end{equation}
Under the stationary proposal law,
\begin{equation}
  R \xrightarrow{\makebox[1em][c]{$\scriptstyled$}} \mathcal N\,\left(-\frac12\sigma_\ell^2,\,\sigma_\ell^2\right).
\end{equation}

Under the standing assumptions, $\tau > 0$. Hence $C_*\tau\ell^3 \neq 0$, and
\begin{equation*}
C_*\tau\,\ell^3\,\xi_1 + C_*\Lambda\,\ell^6
  \sim
  \mathcal N\,\bigl(C_*\Lambda\,\ell^6,\; C_*^2\tau^2\ell^6\bigr),
\end{equation*}
exactly for every $d$, since $\xi_1 \sim \mathcal N(0,1)$. Adding the $o_p(1)$ remainder from \eqref{eq:Rcancel_limit_expansion} gives
\begin{equation*}
  R \xrightarrow{\makebox[1em][c]{$\scriptstyled$}} \mathcal N\,\bigl(C_*\Lambda\,\ell^6,\; C_*^2\tau^2\ell^6\bigr).
\end{equation*}
Using $\Lambda = - C_*\tau^2 /2$ and $\sigma_\ell^2 = C_*^2\tau^2\ell^6$, the mean simplifies to $C_*\Lambda\ell^6 = - \sigma_\ell^2 / 2$, giving the stated form.

\label{cor:acceptance_limit}
Let
\begin{equation}
  a_d(\beta) := \mathbb{E}_\pi\,\left[1 \wedge e^{R}\right]
\end{equation}
denote the stationary mean acceptance probability at step size $\beta$. Under the scaling $\beta=\ell d^{-1/6}$,
\begin{equation}
  a_d(\ell d^{-1/6}) \longrightarrow a(\ell)
  := 2\,\Phi\,\left(-\frac{\sigma_\ell}{2}\right),
\end{equation}
where $\sigma_\ell$ is given by \eqref{eq:sigmaell_def}, and $\Phi$ denotes the standard normal cumulative distribution function.

By Theorem~\ref{thm:gaussian_limit},
\begin{equation}
  R \xrightarrow{\makebox[1em][c]{$\scriptstyled$}} X \sim \mathcal N\,\left(-\frac12\sigma_\ell^2,\sigma_\ell^2\right).
\end{equation}
Since the function $x\mapsto 1 \wedge e^x $ is bounded and continuous, it follows that
\begin{equation}
  a_d(\ell d^{-1/6})=\mathbb{E}_\pi[1 \wedge e^{R}] \longrightarrow \mathbb{E}[1 \wedge e^{X}].
\end{equation}
For $X\sim \mathcal N(-\sigma_\ell^2/2,\sigma_\ell^2)$, the latter expectation is just $2\Phi\left(-\sigma_\ell / 2\right)$. This gives the result.

\label{cor:scaling_trichotomy}
Assume $C_*\neq 0$ and let $\beta_d\to 0$. Under the stationary proposal law, define $\lambda_d := \beta_d^3\sqrt d$, then the following three regimes hold.

\begin{enumerate}
  \item If $\lambda_d\to 0$, then
  \begin{equation}
    R \xrightarrow{\makebox[1em][c]{$\scriptstylep$}} 0,
  \end{equation}
  and hence the stationary acceptance probability satisfies
  \begin{equation}
    a_d(\beta_d)\to 1.
  \end{equation}

  \item If $\lambda_d\to \ell^3\in(0,\infty)$, then
  \begin{equation}
    R \xrightarrow{\makebox[1em][c]{$\scriptstyled$}} \mathcal N\left(-\frac12\sigma_\ell^2,\sigma_\ell^2\right),
  \end{equation}
where $\sigma_\ell$ is defined in \eqref{eq:sigmaell_def}, and therefore
  \begin{equation}
    a_d(\beta_d)\to a(\ell)\,,
  \end{equation}
with $a(\ell)$ defined in Corollary~\ref{cor:acceptance_limit}.
  \item If $\lambda_d\to\infty$, then
  \begin{equation}
    R \xrightarrow{\makebox[1em][c]{$\scriptstylep$}} -\infty,
  \end{equation}
  and hence
  \begin{equation}
    a_d(\beta_d)\to 0.
  \end{equation}
\end{enumerate}

\label{thm:ESJD_limit}
Assume $C_* \neq 0$ and $\beta = \ell d^{-1/6}$ with $\ell > 0$ fixed. Under the stationary proposal law,
\begin{equation}
  \lim_{d \to \infty}
  d^{-2/3}\,\mathrm{ESJD}_d(\ell)
  = \mathcal E(\ell)
  := \ell^2 \,2\Phi\,\left(-\tfrac12 \sigma_\ell\right),
\label{eq:ESJD_limit}
\end{equation}
where $\sigma_\ell$ is defined in \eqref{eq:sigmaell_def}.

\label{lem:geodesic_identity}
For any $z \in \mathcal{M}$ and $v \in T_z\mathcal{M}$ with $\|v\| < r$, let $z' = z + v + \alpha\hat{n} \in \mathcal{M}$ be the projected proposal from Proposition~\ref{prop:sphere_backprojection}. Then
\begin{equation}
  d_{\mathrm{geo}}(z,z') = r\arcsin\,\bigl(\|v\|/r\bigr).
  \label{eq:geodesic_exact}
\end{equation}
In particular,
\begin{equation}
  \bigl|\,d_{\mathrm{geo}}(z,z')^2 - \|v\|^2\,\bigr| \le C\,\|v\|^4/r^2
  \label{eq:geodesic_expand}
\end{equation}
for a constant $C>0$ independent of $z$, $v$ and $r$.

\label{lem:v2_moment}
For any $z \in \mathcal{M}$, under the tangent pCN proposal,
\begin{equation}
  \mathbb{E}[\|v\|^2 \mid z] = \beta^2(d-1) + \gamma^2 \|P_z(b)\|^2.
  \label{eq:v2_mean}
\end{equation}
Define $M_d := \mathbb{E}_\pi[\|v\|^2]$, then under the critical scaling $\beta = \ell d^{-1/6}$ and stationarity,
\begin{equation}
  M_d = \beta^2(d-1)\bigl(1 + O(\beta^2)\bigr)
  = \ell^2 d^{2/3}\bigl(1 + o(1)\bigr),
  \label{eq:Md_leading}
\end{equation}
\begin{equation}
  \mathrm{Var}_\pi(\|v\|^2) = 2\beta^4(d-1)\bigl(1+o(1)\bigr),
  \label{eq:v2_total_var}
\end{equation}
and consequently
\begin{equation}
  \mathbb{E}_\pi\,\left[\left(\frac{\|v\|^2}{M_d} - 1\right)^2\right] = O(d^{-1}).
  \label{eq:eta_L2}
\end{equation}

Conditional on $z$, applying the Gaussian second-moment identity to the tangent pCN proposal gives $\mathbb{E}[\|v\|^2 \mid z] = \| \gamma P_z(b) \|^2 + \mathrm{tr}(\beta^2 P_z)$ with $\mathrm{tr}(P_z) = d-1$ gives \eqref{eq:v2_mean}. Averaging under $\pi$, we have $M_d = \beta^2(d-1) + \gamma^2 \mathbb{E}_\pi[\|P_z(b)\|^2]$. We can write $\|P_z(b)\|^2=\delta^2 d(1-t^2)$. Since $t \xrightarrow{\makebox[1em][c]{$\scriptstylep$}} t^*$ by Lemma~\ref{lem:concentration_t} and $0 \le1 - t^2 \le 1$, bounded convergence gives $\mathbb{E}_\pi[1-t^2] \to 1-(t^*)^2$. Therefore, $\mathbb{E}_\pi[\|P_z(b)\|^2] = \delta^2 d\,\mathbb{E}_\pi[1-t^2] = \delta^2 d(1-(t^*)^2)(1+o(1)) = \tau^2 d(1+o(1))$. Since $\gamma^2=\beta^4 / 4+O(\beta^6)$, it follows that $\gamma^2\mathbb{E}_\pi[\|P_z(b)\|^2]=O(\beta^4 d)$, and hence $M_d=\beta^2(d-1)\bigl(1+O(\beta^2)\bigr)$. Under $\beta=\ell d^{-1/6}$, this becomes $M_d=\ell^2 d^{2/3}(1+o(1))$, proving \eqref{eq:Md_leading}.

For the total variance, basis decomposition gives $\mathrm{Var}(\|v\|^2 \mid z) = 2\beta^4(d-1) + 4\beta^2\gamma^2\|P_z(b)\|^2$, using $\mathrm{Var}(X^2)=2\sigma^4+4\sigma^2\mu^2$ for $X\sim\mathcal N(\mu,\sigma^2)$. We will use $\mathbb{E}_\pi[\|P_z(b)\|^2] = O(d)$ and $\mathrm{Var}_\pi(\|P_z(b)\|^2) = O(d)$, both of which follow from $\|P_z(b)\|^2 = \delta^2 d(1-t^2)$ together with Lemma~\ref{lem:concentration_t}. By the law of total variance, the first term contributes
\begin{equation*}
  \mathbb{E}_\pi[\mathrm{Var}(\|v\|^2 \mid z)]
  = 2\beta^4(d-1) + 4\beta^2\gamma^2\mathbb{E}_\pi[\|P_z(b)\|^2]
  = 2\beta^4(d-1)(1+o(1)),
\end{equation*}
using $\gamma^2 \mathbb{E}_\pi[\|P_z(b)\|^2] = O(\beta^4 d)$, and the second contributes
\begin{equation*}
  \mathrm{Var}_\pi(\mathbb{E}[\|v\|^2 \mid z]) = \gamma^4 \mathrm{Var}_\pi(\|P_z(b)\|^2)
  = O(\beta^8 d) = o(\beta^4 d).
\end{equation*}
Hence $\mathrm{Var}_\pi(\|v\|^2) = 2\beta^4(d-1)(1+o(1))$, proving \eqref{eq:v2_total_var}. Finally, since $\|v\|^2/M_d - 1$ has mean zero,
\begin{equation*}
  \mathbb{E}_\pi\,\left[\left(\frac{\|v\|^2}{M_d} - 1\right)^2\right]
  = \frac{\mathrm{Var}_\pi(\|v\|^2)}{M_d^2}
  = \frac{O(\beta^4 d)}{O(\beta^4 d^2)}
  = O(d^{-1}),
\end{equation*}
proving \eqref{eq:eta_L2}.

\label{lem:factorisation}
Under the critical scaling $\beta = \ell d^{-1/6}$,
\begin{equation}
  \mathbb{E}_\pi[\|v\|^2 \cdot a(z,v)]
  = M_d \cdot \mathbb{E}_\pi[a(z,v)] + o(M_d)\,,
  \label{eq:factorisation}
\end{equation}
where $a(z,v)$ is the acceptance probability of the scheme.

A proposal with $\|v\|\geq r$ is rejected by the convention of Section~\ref{sec:exact-metr-defect}, so $a(z,v)=0$ on $\{\|v\| \geq r\}$ and the integrand in \eqref{eq:ESJD_def} vanishes there; all expectations below thus reduce to integrals over $\{\|v\| <  r\}$, where Lemma~\ref{lem:geodesic_identity} applies. Splitting $d_{\mathrm{geo}}^2=\|v\|^2+(d_{\mathrm{geo}}^2-\|v\|^2)$ and using that $\|v\|^2 a$ also vanishes on $\{\|v\| \ge r\}$,
\begin{equation}
  \mathrm{ESJD}_d(\ell)
  = \mathbb{E}_\pi\bigl[\|v\|^2\,a(z,v)\bigr]
  + \mathbb{E}_\pi\bigl[\bigl(d_{\mathrm{geo}}(z,z')^2-\|v\|^2\bigr)\,a(z,v)\bigr].
  \label{eq:ESJD_split}
\end{equation}

Since $a\le\mathds 1_{\{\|v\| < r\}}$, the bound \eqref{eq:geodesic_expand} gives
\begin{equation*}
  \bigl|\mathbb{E}_\pi[(d_{\mathrm{geo}}^2-\|v\|^2)\,a]\bigr|
  \le \mathbb{E}_\pi\bigl[|d_{\mathrm{geo}}^2-\|v\|^2|\,\mathds 1_{\{\|v\| < r\}}\bigr]
  \le \frac{C}{r^2}\,\mathbb{E}_\pi[\|v\|^4].
\end{equation*}
Using $\eta_d$ defined in the proof of Lemma~\ref{lem:factorisation}, the mean-zero property of $\eta_d$ and \eqref{eq:eta_L2} give $\mathbb{E}_\pi[\|v\|^4]=M_d^2(1+\mathbb{E}_\pi\eta_d^2)=M_d^2(1+O(d^{-1}))$. With $r=\kappa\sqrt d$ and $M_d=\ell^2 d^{2/3}(1+o(1))$ from \eqref{eq:Md_leading},
\begin{equation}
  \bigl|\mathbb{E}_\pi[(d_{\mathrm{geo}}^2-\|v\|^2)\,a]\bigr|
  \le \frac{C\,M_d^2(1+o(1))}{\kappa^2 d}
  = O(d^{1/3}).
  \label{eq:geo_correction_bound}
\end{equation}

By Lemma~\ref{lem:factorisation}, $\mathbb{E}_\pi[\|v\|^2 a]=M_d\,\mathbb{E}_\pi[a]+o(M_d)$. Substituting this and \eqref{eq:geo_correction_bound} into \eqref{eq:ESJD_split},
\begin{equation*}
  \mathrm{ESJD}_d(\ell)=M_d\,\mathbb{E}_\pi[a]+o(M_d)+O(d^{1/3}).
\end{equation*}
Dividing by $d^{2/3}$, and using $M_d/d^{2/3}=\ell^2(1+o(1))$ from \eqref{eq:Md_leading}, with $o(M_d)/d^{2/3}=o(1)$ and $O(d^{1/3})/d^{2/3}=o(1)$, we obtain
\begin{equation*}
  d^{-2/3}\,\mathrm{ESJD}_d(\ell)=\ell^2(1+o(1))\,\mathbb{E}_\pi[a]+o(1).
\end{equation*}
Finally $\mathbb{E}_\pi[a]=a_d(\ell d^{-1/6})\to 2\Phi(-\tfrac12\sigma_\ell)$ by Corollary~\ref{cor:acceptance_limit}, so the right-hand side converges to $\ell^2\cdot 2\Phi(-\tfrac12\sigma_\ell)=\mathcal E(\ell)$, which is \eqref{eq:ESJD_limit}.

\label{prop:drift_family_scaling}
Let $c_\beta = -\tfrac12\beta^2 + \mu\beta^4 + o(\beta^4)$ with $\mu\in\mathds{R}$ fixed, assume stationarity, and let $\beta=\ell d^{-1/6}$ with $\ell>0$ fixed. Then:
\begin{enumerate}
\item[(i)] By Lemma~\ref{lem:g_refined}(i), the expansion \eqref{eq:g_critical_final} holds with $\Lambda$ replaced by
\begin{equation}
\Lambda(\mu) := \tau^2\Bigl(\mu + \frac{s}{8}\Bigr),
\label{eq:Lambda_mu_def}
\end{equation}
the drift contributing $\mu\tau^2\beta^4 d$ through $c_\beta\|P_z(b)\|^2$ while the two curvature contributions are as for tangent pCN.
\item[(ii)] By Lemma~\ref{lem:coeff_general}, the coefficient of $g$ in \eqref{eq:Rcancel_general} with $c=c_\beta$ and $\sigma=\beta$ is $C_*(\mu)\beta^2+o_p(\beta^2)$, whence
\begin{equation}
  R = C_*(\mu)\,\beta^2 g + o_p(1),
  \qquad
  C_*(\mu) := -2\mu - \frac{s}{4},
  \qquad\text{and}\qquad
  \Lambda(\mu) = -\tfrac12 C_*(\mu)\,\tau^2 .
  \label{eq:Cstar_mu}
\end{equation}
\item[(iii)] Consequently, if $C_*(\mu)\neq 0$, the conclusions of Theorem~\ref{thm:gaussian_limit}, Corollary~\ref{cor:acceptance_limit} and Theorem~\ref{thm:ESJD_limit} hold with
\begin{equation}
  \sigma_\ell(\mu) = |C_*(\mu)|\,\tau\,\ell^3,
  \label{eq:sigmaell_mu_def}
\end{equation}
so the limiting ESJD-optimal acceptance probability is $2\Phi(-x_*)\approx 0.574$ for every member of the family, attained at $\ell_*(\mu) = \bigl(2x_*/(|C_*(\mu)|\tau)\bigr)^{1/3}$.
\end{enumerate}

\label{cor:tangent_mala}
Tangent MALA is the member $\mu=0$, with
\begin{equation}
  C_*^{\mathrm{MALA}} = -\frac{s}{4} < 0
  \qquad\text{for all }\delta,\kappa>0 .
\end{equation}
Hence tangent MALA obeys the critical scaling $\beta=\ell d^{-1/6}$ with $\sigma_\ell(0)=(s/4)\,\tau\ell^3$ by \eqref{eq:sigmaell_mu_def}, and has limiting ESJD-optimal acceptance $\approx 0.574$, and the exceptional cancellation $C_*^{\mathrm{MALA}}=0$ never occurs for tangent MALA.

\label{cor:tangent_rw}
For $c_\beta\equiv 0$ (RWMH) the proposal log-ratio vanishes identically, so $R=-g$ exactly. By Lemma~\ref{lem:g_refined}(ii), the $O(\beta^2 d)$ cancellation present for tangent pCN does not occur, and instead $g = \beta\tau\sqrt d\,\xi_1 + \tfrac12\tau^2\beta^2 d\,(1+o_p(1))$. Hence with $\beta=\ell d^{-1/2}$, $\ell>0$ fixed,
\begin{equation}
  R \xrightarrow{\makebox[1em][c]{$\scriptstyled$}} \mathcal{N}\Bigl(-\tfrac12\tau^2\ell^2,\ \tau^2\ell^2\Bigr),
  \qquad
  a_d(\ell d^{-1/2})\to 2\Phi\Bigl(-\frac{\tau\ell}{2}\Bigr),
  \qquad
  \mathrm{ESJD}_d(\ell)\to \ell^2\cdot 2\Phi\Bigl(-\frac{\tau\ell}{2}\Bigr),
\end{equation}
with ESJD-optimal acceptance $2\Phi(-x_*^{\mathrm{RW}})\approx 0.234$, where $x_*^{\mathrm{RW}}\approx 1.1906$ solves $2\Phi(-x)=x\phi(x)$, attained at $\ell_* = 2x_*^{\mathrm{RW}}/\tau$.

\label{thm:joint_diffusion_limit}
Fix $\delta,\kappa,\ell>0$, assume $C_*\ne0$, take $\beta=\ell d^{-1/6}$, and start the full chain in stationarity, $z_0\sim\pi_d$. Then, as $d\to\infty$,
\begin{equation}
 (S^{(d)},X^{(d)}) \Rightarrow (S, X)
 \qquad\text{in }D([0,\infty),\mathds{R}^2),
 \label{eq:joint_process_convergence}
\end{equation}
where $S$ and $X$ are independent stationary OU processes satisfying

\begin{align}
 dS(u)&=-\frac{h(\ell)}{2\sigma_{t^*}^2}S(u)\,du +\sqrt{h(\ell)}\,dB(u),
 \qquad S(0)\sim\mathcal{N}(0,\sigma_{t^*}^2)\,,
 \label{eq:scalar_OU_limit}\\
 dX(u)&=-\frac{s}{2}h_\perp(\ell)X(u)\,du +\sqrt{h_\perp(\ell)}\,dB_\perp(u),
 \qquad X(0)\sim\mathcal{N}(0,s^{-1}).
 \label{eq:transverse_OU_limit}
\end{align}
Here $B$ and $B_\perp$ are independent Brownian motions in $\mathds{R}$. The speed functions are

\begin{equation}
    h(\ell)=\left(\frac{\tau}{\delta\kappa}\right)^2\ell^2K(\sigma_\ell)\,,
    \label{eq:h_diffusion}
\end{equation}
and 
\begin{equation}
 h_\perp(\ell)=\ell^2\,2\Phi(-\sigma_\ell/2)=\mathcal E(\ell),
 \label{eq:h_transverse}
\end{equation}
with $\sigma_\ell$ given in \eqref{eq:sigmaell_def} and
\begin{equation}
K(\sigma) =\left(2+\frac{\sigma^2}{2}\right)\Phi(-\sigma/2) -\sigma\phi(\sigma/2)\,.
 \label{eq:K_diffusion}
\end{equation}

\label{rmk:K_properties}
We have $K(0)=1$ and $K'(\sigma)=\sigma\Phi(-\sigma/2)-2\phi(\sigma/2)<0$ for $\sigma\ge0$ by Mills' inequality, so $K$ is strictly decreasing. We also have that $K(\sigma) <2\Phi(-\sigma/2)$ for $\sigma>0$ by the same inequality. Considering the different coordinate scales, the speeds satisfy
\begin{equation}
    \frac{h(\ell)}{(\tau/(\delta\kappa))^2h_\perp(\ell)} =\frac{K(\sigma_\ell)}{2\Phi(-\sigma_\ell/2)}<1.
\end{equation}
The leading longitudinal increment and the log acceptance ratio depend on the same Gaussian variable $\xi_1$ and hence cannot be treated as asymptotically independent. In a transverse direction, the leading noise is independent of $\xi_1$, its odd moments against the acceptance indicator vanish, and its acceptance-weighted second moment converges to the acceptance probability. This gives the factor $K$ in $h$ and the factor $2\Phi(-\sigma_\ell/2)$ in $h_\perp$.

\label{thm:fixed_step}
Fix $\delta,\kappa>0$ and $\beta\in(0,1)$. Consider the chain generated by the intrinsic proposal \eqref{eq:intrinsic_proposal}, started in stationarity, $z_0\sim\pi_d$. Set $g=J_s=0$ and $R=-\infty$ on projection failure.
\begin{enumerate}
\item[(i)] The projection failure probability tends to zero, and
\begin{equation}
  \frac{g}{\sqrt d}\xrightarrow{\makebox[1em][c]{$\scriptstyled$}}\bar g,
  \qquad
  \sqrt d\,J_s\xrightarrow{\makebox[1em][c]{$\scriptstyled$}}\bar J_s,
  \qquad
  R\xrightarrow{\makebox[1em][c]{$\scriptstyled$}}\bar R,
  \label{eq:fixed_step_limit}
\end{equation}
jointly. Here $\zeta\sim\mathcal{N}(0,\sigma_{t^*}^2)$ and $\xi_1,\omega\sim\mathcal{N}(0,1)$ are independent, and
\begin{align}
  \bar g &=
  \delta\kappa\frac{\rho^2-q}{q}\,\zeta +\frac{\rho\beta\tau}{q\sqrt s}\,\xi_1 +\frac{\beta^2\tau^2}{\sqrt2\,q\,s}\,\omega,
\label{eq:gbar}\\
  \bar J_s &=
  \frac1s\left[\frac{1-\rho}{1+\rho}\left(\frac{\delta\rho}{\kappa q}\,\zeta +\frac{\beta\tau}{\sqrt s\,\kappa^2q}\,\xi_1\right) +\frac{\gamma}{\sqrt2\,\kappa^2q}\,\omega \right],
\label{eq:Jbar}\\
  \bar R &=
  \bar J_s\bar g +\frac{1-\rho}{1+\rho} \frac{\bar g^2}{2s\kappa^2}.
\label{eq:Rbar}
\end{align}
Consequently, the stationary acceptance probability satisfies
\begin{equation}
  a_d(\beta)\longrightarrow \mathbb{E}[1 \wedge e^{\bar R}]\in(0,1).
  \label{eq:fixed_step_acceptance}
\end{equation}
\item[(ii)] For every fixed $m\in\mathbb N$, the process $(\zeta_k,X_k)_{0\le k\le m}$ converges in law to the stationary Markov chain whose initial law is given by $(\zeta_0,X_0) \sim \mathcal{N}(0,\sigma_{t^*}^2) \otimes \mathcal{N}(0,s^{-1})$ and the following transition: from the current state $(\zeta_k,X_k)$, draw independent $\xi_1,\xi_2, \omega\sim\mathcal{N}(0,1)$ and $u\sim U(0,1)$. Form $\bar g,\bar J_s,\bar R$ using \eqref{eq:gbar}--\eqref{eq:Rbar} with $\zeta=\zeta_k$, and set
\begin{equation}
  (\zeta_{k+1},X_{k+1}) =
  \begin{cases}
    \displaystyle
    \left(\zeta_k+\frac{\bar g}{\delta\kappa},\rho X_k+\frac{\beta}{\sqrt s}\xi_2 \right),
    & \log u<\bar R,\\[1.5ex]
    (\zeta_k,X_k), & \text{otherwise}.
  \end{cases}
\label{eq:limit_kernel}
\end{equation}
The limiting kernel is reversible with respect to its initial law.
\end{enumerate}

\label{lem:good_event}
Let $\Omega_d := \{\,W + 2\xi_1^2 \le 2d\,\}$, where
$W\sim\chi^2_{d-2}$ and $\xi_1\sim\mathcal{N}(0,1)$ are the proposal statistics
of the scalar reduction. Then there is a constant $c>0$ with
\begin{equation*}
  \mathbb P(\Omega_d^{\complement})\le e^{-cd}
  \qquad\text{for all } d\ge 3 .
\end{equation*}
Moreover, there exist $\beta_0, C_0>0$, depending only on
$(\delta,\kappa)$, such that for every $\beta\le\beta_0$, pathwise on
$\Omega_d$,
\begin{equation}
  \|v\|^2 \le C_0\,\beta^2 d \le \tfrac12\,r^2 ,
  \label{eq:v2_pathwise_bound}
\end{equation}
for any drift proposal $v=c_\beta P_z(b)+\beta P_z\xi$ with $|c_\beta|\le\beta$ with
$C_0 = 2(1+\delta^2)$ and $\beta_0^2 = 1 \wedge \kappa^2/(4(1+\delta^2))$. In particular, on $\Omega_d$ the projection onto $\mathcal{M}$ exists and the third-order expansion \eqref{eq:alpha_third_order_app} of $\alpha$ is
valid.

\label{lem:g_refined}
Let $\Omega_d$ and $\beta_0$ be as in Lemma~\ref{lem:good_event}. Assume stationarity and let $\beta=\beta_d\to0$ with $\beta_d\le\beta_0$. Then, on $\Omega_d$:
\begin{enumerate}
\item[(i)] If $c_\beta=-\tfrac12\beta^2+\mu\beta^4+o(\beta^4)$ with
$\mu\in\mathds{R}$ fixed, then
\begin{equation}
  g = \beta\tau\sqrt d\,\xi_1
     + \Lambda(\mu)\,\beta^4 d
     + O_p(\beta)
     + O_p(\beta^2\sqrt d)
     + O_p(\beta^3\sqrt d)
     + o(\beta^4 d).
  \label{eq:g_refined_general}
\end{equation}
Here $\Lambda(\mu)$ and $C_*(\mu)$ are defined in \eqref{eq:Lambda_mu_def} and \eqref{eq:Cstar_mu}, respectively. If moreover $c_\beta=-\tfrac12\beta^2+\mu\beta^4+O(\beta^6)$, the final term improves to $O(\beta^6 d)$.
\item[(ii)] If $c_\beta\equiv0$, then
\begin{equation}
  g=\beta\tau\sqrt d\,\xi_1+\tfrac12\tau^2\beta^2 d
    +O_p(\beta)+O_p(\beta^2\sqrt d)+O_p(\beta^4 d).
  \label{eq:g_refined_rw}
\end{equation}
\end{enumerate}

By Lemma~\ref{lem:good_event} which is applicable since $|c_\beta|\le\beta$ for all sufficiently small $\beta$, $\mathbb P(\Omega_d^{\complement})\le e^{-cd}$ and, pathwise on $\Omega_d$, $\|v\|^2\le C_0\beta^2 d\le r^2/2$, so the expansion \eqref{eq:alpha_third_order_app} of $\alpha$ is valid on $\Omega_d$.

\emph{Step 1 (expansion of $\|v\|^2$).}
Since $c_\beta^2=\tfrac14\beta^4+O(\beta^6)$, expanding
\eqref{eq:g_split_general} with \eqref{eq:blocks_refined} gives
\begin{equation}
  \|v\|^2=\beta^2 d+\frac{\tau^2}{4}\beta^4 d
   +O_p(\beta^2\sqrt d)+O_p(\beta^3\sqrt d)+O(\beta^6 d),
  \label{eq:v2_refined}
\end{equation}
where $O_p(\beta^2\sqrt d)$ absorbs $\beta^2(W-(d-2))$, $-2\beta^2$,
$\beta^2\xi_1^2$ and $\tfrac14\beta^4(\|P_z(b)\|^2-\tau^2 d)=O_p(\beta^4\sqrt d)$,
while $O_p(\beta^3\sqrt d)$ is the cross term $2c_\beta \|P_z(b)\|\beta\xi_1$
and $O(\beta^6 d)$ collects the deterministic tail of $c_\beta^2 \|P_z(b)\|^2$.

\emph{Step 2 (assembling $g$, case (i)).}
Substituting \eqref{eq:alpha_third_order_app} into
\eqref{eq:g_split_general},
\begin{equation}
  g=c_\beta \|P_z(b)\|^2+\beta \|P_z(b)\|\xi_1
    -\frac{\langle\hat{n},b\rangle}{2r}\,\|v\|^2
    -\frac{\langle\hat{n},b\rangle}{8r}\,\frac{\|v\|^4}{r^2}
    +\vartheta\,\frac{\langle\hat{n},b\rangle\|v\|^6}{r^5}.
  \label{eq:g_assembled}
\end{equation}
We expand each term, using throughout that $|\langle\hat{n},b\rangle/r|\le\delta/\kappa$
is a bounded multiplier.

(a) $\beta \|P_z(b)\|\xi_1=\beta\tau\sqrt d\,\xi_1+O_p(\beta)$ by
\eqref{eq:blocks_refined}.

(b) \emph{Cancellation at order $\beta^2 d$.} The contributions of $c_\beta \|P_z(b)\|^2$ and
$-(\langle\hat{n},b\rangle/2r)\|v\|^2$ at this order cancel. Indeed, \eqref{eq:v2_refined} gives
\begin{equation}
  -\frac{\beta^2}{2}
  \left[
    \bigl(\|P_z(b)\|^2- \tau^2d\bigr)
    +d\left(\frac{\langle\hat{n},b\rangle}{r}+\tau^2\right)\right]
  = O_p(\beta^2\sqrt d),
  \label{eq:cancellation_quantified}
\end{equation}
by the two estimates in \eqref{eq:blocks_refined}. This is the cancellation of
Lemma~\ref{lem:g_cancellation}.

(c) \emph{Drift contribution at order $\beta^4 d$.}
$\mu\beta^4 \|P_z(b)\|^2=\mu\tau^2\beta^4 d+O_p(\beta^4\sqrt d)$, and the
$o(\beta^4)$ tail of $c_\beta$ contributes
$o(\beta^4)\cdot \|P_z(b)\|^2=o(\beta^4 d)$ (deterministically, since
$\|P_z(b)\|^2\le\delta^2 d$); under the stronger hypothesis this is
$O(\beta^6 d)$.

(d) \emph{First curvature contribution.} The
$\tfrac{\tau^2}4\beta^4 d$ part of \eqref{eq:v2_refined}, multiplied
by $-\langle\hat{n},b\rangle/(2r)$ yields
$\tfrac{\tau^4}8\beta^4 d+O_p(\beta^4\sqrt d)$; the remainders of
\eqref{eq:v2_refined} stay $O_p(\beta^2\sqrt d)+O_p(\beta^3\sqrt d)
+O(\beta^6 d)$ under the bounded multiplier.

(e) \emph{Second curvature contribution.} Squaring
\eqref{eq:v2_refined} and dividing by $r^2=\kappa^2 d$,
\begin{equation*}
  \frac{\|v\|^4}{r^2} =\frac{\beta^4 d}{\kappa^2} +\frac{\tau^2}{2\kappa^2}\beta^6 d +\frac{\tau^4}{16\kappa^2}\beta^8 d + O_p(\beta^4\sqrt d)+O_p(\beta^5\sqrt d)+O(\beta^8 d)+O_p(\beta^4),
\end{equation*}
hence

\begin{align*}
  -\frac{\langle\hat{n},b\rangle}{8r}\,\frac{\|v\|^4}{r^2}
  &=\Bigl(\frac{\tau^2}{8}+O_p(d^{-1/2})\Bigr) \frac{\beta^4 d}{\kappa^2} +O_p(\beta^2\sqrt d)+O(\beta^6 d)\\
  &=\frac{\tau^2}{8\kappa^2}\,\beta^4 d +O_p(\beta^2\sqrt d)+O_p(\beta^4\sqrt d)+O(\beta^6 d).
\end{align*}

(f) \emph{Cubic remainder.}
On $\Omega_d$, by \eqref{eq:v2_pathwise_bound}, pathwise
\begin{equation*}
  |\langle\hat{n},b\rangle|\,\frac{\|v\|^6}{r^5}
  \le \delta\sqrt d\;\frac{C_0^3\beta^6 d^3}{\kappa^5 d^{5/2}}
  = O(\beta^6 d) = o(\beta^4 d),
\end{equation*}
now a deterministic bound.

Summing (a)--(f) and consolidating
$O_p(\beta^4\sqrt d),O_p(\beta^2)\subset O_p(\beta^2\sqrt d)$ (valid
for $\beta\le1$, $d\ge1$) and $O(\beta^6 d)\subset o(\beta^4 d)$
gives \eqref{eq:g_refined_general} with
$\Lambda(\mu)=\mu\tau^2+\tfrac{\tau^4}8+\tfrac{\tau^2}{8\kappa^2}
=\tau^2(\mu+s/8)$.

\emph{Step 3 (case (ii)).}
With $c_\beta\equiv0$, $\|v\|^2=\beta^2(W+\xi_1^2)
=\beta^2 d+O_p(\beta^2\sqrt d)$, and \eqref{eq:g_assembled} becomes
\begin{equation*}
  g=\beta \|P_z(b)\|\xi_1
   +\Bigl(\frac{\tau^2}{2}+O_p(d^{-1/2})\Bigr)
    \bigl(\beta^2 d+O_p(\beta^2\sqrt d)\bigr)
   +O_p(\beta^4 d)+O_p(\beta^6 d),
\end{equation*}
the $O_p(\beta^4 d)$ bounding the $\|v\|^4$ term and the
$O_p(\beta^6 d)$ the cubic remainder; no cancellation occurs because
the $c_\beta \|P_z(b)\|^2$ term is absent. With (a), this is
\eqref{eq:g_refined_rw}.

\label{lem:coeff_general}
Under the hypotheses of Lemma~\ref{lem:g_refined}(i), on the event
$\Omega_d$ of Lemma~\ref{lem:good_event}, for every $\beta_d\to0$,
\begin{equation}
  -1-\frac{2c_\beta}{\beta^2}=-2\mu\beta^2+o(\beta^2),
  \qquad
  -\frac{c_\beta}{\beta^2}\,\frac{\alpha}{r}
   =-\frac{\beta^2}{4\kappa^2}+o_p(\beta^2),
  \qquad
  \frac{c_\beta^2}{\beta^2}\,\frac{\langle\hat{n},b\rangle}{r}
   =-\frac{\tau^2}{4}\beta^2+o_p(\beta^2),
  \label{eq:coeff_general}
\end{equation}
and $\dfrac{c_\beta^2}{2\beta^2}\,\dfrac{g^2}{r^2}
=O_p\bigl(\beta^4(1+\beta^6 d)\bigr)$.

\label{lem:conditional_expansion_diffusion}
Let $\beta=\ell \varepsilon$ and assume $C_*\ne0$. For every fixed $L>0$, every integer $m \ge 1$ and all sufficiently large $d$ (so that $\beta\le\beta_0$), on the event $\Omega_d$ of Lemma~\ref{lem:good_event},
\begin{align}
    g &= \varepsilon^{-2}g_0+\varepsilon^{-1}g_{1,d}+g_{2,d},
    \label{eq:g_conditional_expansion}\\
    R &=R_0+\varepsilon R_{1,d}+R_{2,d},
    \label{eq:R_conditional_expansion}
\end{align}
where
\begin{equation}
    \sup_{|\zeta|\le L} \mathbb{E}_\zeta[|g_{2,d}|^m\mathds1_{\Omega_d}]=O(1),
    \qquad
 \sup_{|\zeta|\le L}
 \mathbb{E}_\zeta[|R_{2,d}|^m\mathds1_{\Omega_d}]
 =O(\varepsilon^{2m}).
 \label{eq:conditional_remainder_bounds}
\end{equation}
Moreover, for every fixed $m$,
\begin{equation}
    \sup_{\zeta}
 \mathbb{E}_\zeta\!\left[
 |\Delta\zeta|^m\mathds1_{\Omega_d^{\complement}}\right]
 \le 2^m d^{m/2}e^{-cd}.
 \label{eq:bad_event_increment_bound}
\end{equation}

Fix $L>0$ and $1\le m<\infty$. For $|\zeta|\le L$, we can write $t=t^*+\zeta\varepsilon^3$. All bounds below hold uniformly over this set. We use the event $\Omega_d$ of Lemma~\ref{lem:good_event}. It depends only on $(\xi_1,W)$ and satisfies
$\mathbb P(\Omega_d^{\complement})\le e^{-cd}$ with $c>0$. For all
sufficiently large $d$, the critical step size $\beta=\ell\varepsilon$ is below the constant $\beta_0$ of that lemma; hence, pathwise on $\Omega_d$, $\|v\|^2\le r^2/2$ and the third-order expansion
\eqref{eq:alpha_third_order_app} is valid.

In the notation of \eqref{eq:diffusion_bookkeeping}, the identities \eqref{eq:nb_expansion} and \eqref{eq:P_expansion} exactly read
\begin{equation}
    \|P_z(b)\|^2=\tau^2\varepsilon^{-6}
        +2\delta\kappa\tau^2\zeta\varepsilon^{-3}
        -\delta^2\zeta^2,
 \qquad
 \frac{\langle\hat{n},b\rangle}{r}
   =-\tau^2+\frac{\delta\zeta}{\kappa}\varepsilon^3\,.
 \label{eq:pz2_nb_conditional_blocks}
\end{equation}
Taylor expansion of the square root, uniformly for $|\zeta|\le L$, gives in addition
\begin{equation}
\|P_z(b)\| =\tau\varepsilon^{-3} +\delta\kappa\tau\zeta +O(\varepsilon^3).
\label{eq:pz_conditional_blocks}
\end{equation}
We also have
\begin{align}
\gamma &=-\tfrac12\ell^2\varepsilon^2 -\tfrac18\ell^4\varepsilon^4 + O(\varepsilon^6)\,,
\label{eq:gamma_conditional_blocks}\\
W &=\varepsilon^{-6}-2 +\sqrt2\varepsilon^{-3}\sqrt{1-2\varepsilon^6}\,\widehat W_d.
\label{eq:W_conditional_blocks}
\end{align}
For every fixed $p<\infty$, $\sup_{d\ge3}\mathbb{E}|\widehat W_d|^p<\infty$. For convenience, set $V_d:=\|v\|^2$. Then expanding the exact scalar reduction \eqref{eq:scalar_reduction} and using \eqref{eq:pz_conditional_blocks}--\eqref{eq:W_conditional_blocks} gives
\begin{equation}
V_d=\ell^2\varepsilon^{-4} +\frac{1}{4}\ell^4\tau^2\varepsilon^{-2}
     +\sqrt2\ell^2\varepsilon^{-1}\widehat W_d+\widetilde V_d,
 \qquad \sup_{|\zeta|\le L} \mathbb{E}_\zeta\!\left[|\widetilde V_d|^p\right] = O(1)
 \label{eq:V_conditional_expansion}
\end{equation}
for every fixed $p$. On $\Omega_d$, substituting \eqref{eq:alpha_third_order_app} into
the scalar representation of $g$ gives
\begin{equation}
  g =\gamma\|P_z(b)\|^2+\beta\|P_z(b)\|\xi_1
    -\frac{\langle\hat{n},b\rangle}{2r}V_d -\frac{\langle\hat{n},b\rangle}{8r}\frac{V_d^2}{r^2}
    +\vartheta\frac{\langle\hat{n},b\rangle}{r} \frac{V_d^3}{r^4},
  \qquad |\vartheta|\le1.
\label{eq:g_conditional_assembled}
\end{equation}
The terms are expanded as in the proof of Lemma~\ref{lem:g_refined} and so the first four terms in \eqref{eq:g_conditional_assembled} satisfy
\begin{align}
  \gamma\|P_z(b)\|^2
  &=-\tfrac12\ell^2\tau^2\varepsilon^{-4}
    -\tfrac18\ell^4\tau^2\varepsilon^{-2}
    -\ell^2\delta\kappa\tau^2\zeta\varepsilon^{-1}
    +\mathcal E_{1,d},
    \label{eq:g_conditional_term1}\\
  \beta\|P_z(b)\|\xi_1
  &=\ell\tau\xi_1\varepsilon^{-2}
    +\mathcal E_{2,d},
    \label{eq:g_conditional_term2}\\
  -\frac{\langle\hat{n},b\rangle}{2r}V_d
  &=\tfrac12\ell^2\tau^2\varepsilon^{-4}
    +\tfrac18\ell^4\tau^4\varepsilon^{-2} \notag\\
  &\quad
    +\left(
       -\frac{\ell^2\delta}{2\kappa}\zeta
       +\frac{\ell^2\tau^2}{\sqrt2}\widehat W_d
     \right)\varepsilon^{-1}
    +\mathcal E_{3,d},
    \label{eq:g_conditional_term3}\\
  -\frac{\langle\hat{n},b\rangle}{8r}\frac{V_d^2}{r^2}
  &=\frac{\ell^4\tau^2}{8\kappa^2}\varepsilon^{-2}
    +\mathcal E_{4,d}\,,
  \label{eq:g_conditional_term4}
\end{align}
where, for $j\in\{1,\ldots,4\}$ the $\mathcal E_{j,d}$ capture all positive powers of $\varepsilon$, so that, for every fixed $p$,
\begin{equation}
\sup_{|\zeta|\le L} \mathbb{E}_\zeta\!\left[|\mathcal E_{j,d}|^p\mathds1_{\Omega_d}\right]
  =O(1).
  \label{eq:g_conditional_component_remainders}
\end{equation}
Finally, Lemma~\ref{lem:good_event} gives $V_d\le C_0\ell^2\varepsilon^{-4}$ on
$\Omega_d$, so for the last term \eqref{eq:g_conditional_assembled} we have the pathwise bound
\begin{equation}
\left|\vartheta\frac{\langle\hat{n},b\rangle}{r} \frac{V_d^3}{r^4}\right|
 \le \frac{\delta}{\kappa}\, \frac{C_0^3\ell^6\varepsilon^{-12}}{\kappa^4\varepsilon^{-12}} = O(1).
 \label{eq:g_conditional_cubic}
\end{equation}

The order $\varepsilon^{-4}$ terms in \eqref{eq:g_conditional_term1} and
\eqref{eq:g_conditional_term3} cancel. At order $\varepsilon^{-2}$, the remaining coefficient is
\begin{equation}
\ell\tau\xi_1 +\tfrac18 \ell^4\tau^2 (s-1) = \ell\tau\xi_1+\Lambda\ell^4 = g_0\,,
\end{equation}
using $\Lambda$ as defined in \eqref{eq:g_critical_final}. At order $\varepsilon^{-1}$, the coefficient is
\begin{equation}
-\ell^2\delta\left(\kappa\tau^2+\frac{1}{2\kappa}\right)\zeta +\frac{\ell^2\tau^2}{\sqrt2}\,\widehat W_d = g_{1,d}.
\end{equation}
Defining $g_{2,d}$ by the exact remainder in \eqref{eq:g_conditional_expansion}, \eqref{eq:g_conditional_component_remainders} and \eqref{eq:g_conditional_cubic} prove the first bound in
\eqref{eq:conditional_remainder_bounds}.

On $\Omega_d$, use the split $R=Jg+Q$ of \eqref{eq:R_JQ_decomposition}.  We require the leading term of $J$ with an $O(\varepsilon^4)$ remainder; in particular, there is no order $\varepsilon^3$ term. Substituting \eqref{eq:V_conditional_expansion} into the expansion \eqref{eq:alpha_third_order_app} of $\alpha / r$ and using $r^2=\kappa^2\varepsilon^{-6}$ gives
\begin{equation}
\frac{\alpha}{r} =-\frac{\ell^2}{2\kappa^2}\varepsilon^2+\widetilde A_d,
 \qquad \sup_{|\zeta|\le L} \mathbb{E}_\zeta\!\left[|\widetilde A_d|^p \mathds1_{\Omega_d} \right] = O(\varepsilon^{4p})\,,
 \label{eq:alpha_r_conditional}
\end{equation}
for every fixed $p$. The $\varepsilon^{-2}$ correction in $V_d$ and the leading term $V_d^2$ both contribute at order $\varepsilon^4$ to $\alpha/r$, all remaining terms are smaller. Moreover, the
order $\varepsilon^3$ correction in $\langle\hat{n} ,b\rangle/r$ is multiplied in $J$ by $(1-\rho)/(1+\rho)=\tfrac14\ell^2\varepsilon^2+O(\varepsilon^4)$ and therefore first contributes at order $\varepsilon^5$. Together with $1/(1+\rho)=\tfrac12+O(\varepsilon^2)$, these give
\begin{equation}
    J=C_*\ell^2\varepsilon^2 + \widetilde J_d, \qquad \sup_{|\zeta|\le L} \mathbb{E}_\zeta\!\left[|\widetilde J_d|^p \mathds1_{\Omega_d} \right] = O(\varepsilon^{4p})\,.
    \label{eq:J_conditional_expansion}
\end{equation}
From the expansion of $g$ and the previous remainder bounds, we have $\sup_{|\zeta|\le L} \mathbb{E}_\zeta\!\left[
|g|^p\mathds1_{\Omega_d} \right]=O(\varepsilon^{-2p})$. Hence
\begin{equation}
\sup_{|\zeta|\le L} \mathbb{E}_\zeta\!\left[
|Q|^p\mathds1_{\Omega_d} \right] =O(\varepsilon^{4p})\,.
\end{equation}
Moreover, since $R_0 + \varepsilon R_{1,d} = C_*\ell^2\varepsilon^2 \left( \varepsilon^{-2}g_0 + \varepsilon^{-1}g_{1,d} \right)$, the exact remainder in \eqref{eq:R_conditional_expansion} is
\begin{equation}
    R_{2,d} = C_*\ell^2\varepsilon^2g_{2,d} +\widetilde J_d\,g+Q.
\label{eq:R2_exact_decomposition}
\end{equation}
The first term has $m$-th moment $O(\varepsilon^{2m})$, the second has the same bound by H\"older and \eqref{eq:J_conditional_expansion}, and the last term has $m$-th $O(\varepsilon^{4m})$. This proves the second bound in \eqref{eq:conditional_remainder_bounds}.

For the final bound we have that the accepted chain always has $t_k,t_{k+1}\in[-1,1]$; a failed projection
is a rejection. Therefore, $|\Delta\zeta|=\sqrt d\,|t_{k+1}-t_k|\le2\sqrt d$ deterministically. By Lemma~\ref{lem:good_event}, $\mathbb P(\Omega_d^{\complement})\le e^{-cd}$, and this bound is independent of the current $\zeta$. Therefore,
\begin{equation}
    \sup_\zeta\mathbb{E}_\zeta\!\left[ |\Delta\zeta|^m\mathds1_{\Omega_d^{\complement}} \right]
    \le (2\sqrt d)^m \mathbb P(\Omega_d^{\complement}) \le
    2^m d^{m/2}e^{-cd}.
\end{equation}
This proves \eqref{eq:bad_event_increment_bound}.

Set $a:=C_*\tau\ell^3$ so that $R_0=a\xi_1-a^2 /2$ and $\sigma_\ell=|a|$. The transformation $(\xi_1,a)\mapsto(-\xi_1,-a)$ preserves the law of $\xi_1$ and leaves $R_0$ unchanged, while $\xi_1-\frac a2 \,\mapsto\, -\left(\xi_1-\frac a2\right)$. So identities involving the square of this quantity are unchanged and the identities involving its first power change sign on both
sides. It therefore suffices to treat $a>0$, and then $\sigma_\ell=a$.

For $a>0$, $R_0<0$ exactly when $\xi_1<a/2$ and so $\mathcal A(R_0) = \mathds1_{\{\xi_1\ge a/2\}} +e^{R_0}\mathds1_{\{\xi_1<a/2\}}$. Completing the square gives $e^{ax-a^2/2}\phi(x)=\phi(x-a)$. Consequently, for each of the polynomial functions $F$ used below,
\begin{equation}
\mathbb{E}\!\left[F(\xi_1)\mathcal A(R_0)\right] = \int_{a/2}^{\infty}F(x)\phi(x)\,dx +\int_{-\infty}^{-a/2}F(y+a)\phi(y)\,dy,
\label{eq:acceptance_master}
\end{equation}
where the second integral follows from the substitution $y=x-a$. Taking $F\equiv1$ in \eqref{eq:acceptance_master} proves \eqref{eq:A_moment_diffusion}. Taking $F(x)=x-a/2$ and substituting $y=-x$ in the second integral of \eqref{eq:acceptance_master}, the two integrals cancel and so we have $\mathbb{E}\!\left[\left(\xi_1-\frac a2\right)\mathcal A(R_0)\right]=0$, showing~\eqref{eq:A_first_moment_disappears}.
For \eqref{eq:K_moment_diffusion}, set $c:=a/2$ and take
$F(x)=(x-c)^2$ in \eqref{eq:acceptance_master}. By symmetry of $\phi$,
the two integrals are equal, and using truncated Gaussian moments we get
\begin{align*}
\mathbb{E}\!\left[\left(\xi_1-\frac a2\right)^2\mathcal A(R_0)\right] &= 2\int_c^\infty(x-c)^2\phi(x)\,dx\\
&=2\bigl[(1+c^2)\Phi(-c)-c\phi(c)\bigr]\\
&=\left(2+\frac{\sigma_\ell^2}{2}\right) \Phi(-\sigma_\ell/2) -\sigma_\ell\phi(\sigma_\ell/2) = K(\sigma_\ell)\,.
\end{align*}
The random variable $(\xi_1-a/2)^2\mathcal A(R_0)$ is nonnegative and a.s.~not zero, so $K(\sigma_\ell)>0$.
Finally, the same change of variables gives
\begin{equation}
\mathbb{E}\!\left[\left(\xi_1-\frac a2\right)e^{R_0}\mathds1_{\{R_0<0\}}\right]= \int_{-\infty}^{-a/2}\left(y+\frac a2\right)\phi(y)\,dy = \frac a2\Phi(-a/2)-\phi(a/2).
\end{equation}
For general sign of $C_*$ the symmetry above gives a factor $\operatorname{sgn}(C_*)$ on the second term which proves \eqref{eq:derivative_moment_diffusion}.

\label{prop:conditional_moments_diffusion}
As $d\to\infty$, for every $L>0$,
\begin{align}
    \sup_{|\zeta|\le L}\left|d^{1/3}\mathbb{E}_\zeta[\Delta\zeta]+\frac{h(\ell)}{2\sigma_{t^*}^2}\zeta\right| &\xrightarrow{\makebox[1em][c]{$\scriptstyle$}} 0\,,
\label{eq:conditional_drift_diffusion}\\
    \sup_{|\zeta|\le L} \left|d^{1/3}\mathbb{E}_\zeta[(\Delta\zeta)^2]-h(\ell)\right| &\xrightarrow{\makebox[1em][c]{$\scriptstyle$}} 0\,,
\label{eq:conditional_variance_diffusion}\\
    \sup_{|\zeta|\le L}d^{1/3}\mathbb{E}_\zeta[(\Delta\zeta)^4] &\xrightarrow{\makebox[1em][c]{$\scriptstyle$}} 0\,,
\label{eq:conditional_fourth_diffusion}
\end{align}
where $h$ is defined in \eqref{eq:h_diffusion}.

By \eqref{eq:bad_event_increment_bound}, it suffices to work on $\Omega_d$. For every $H$ measurable with respect to $(\xi_1,W)$, integrating over $U$ gives $\mathbb{E}[H\mathds1_{\mathrm{acc}}\mid\xi_1,W] = H\mathcal A(R)$. The function $\mathcal A$ is Lipschitz, has a.e. derivative $\mathcal A'(x)=e^x\mathds1_{\{x<0\}}$. Using \eqref{eq:R_conditional_expansion}, it satisfies
\begin{align}
&\left| \mathcal A(R)-\mathcal A(R_0) -(\varepsilon R_{1,d}+R_{2,d})\mathcal A'(R_0) \right| \notag\\
& \qquad \le \tfrac12|\varepsilon R_{1,d}+R_{2,d}|^2 +2|\varepsilon R_{1,d}+R_{2,d}| \mathds1_{\{|R_0|\le|\varepsilon R_{1,d}+R_{2,d}|\}} .
\label{eq:acceptance_kink_bound}
\end{align}
Since $R_0=C_*\ell^2g_0$, on the event in the second term of \eqref{eq:acceptance_kink_bound} we have $|g_0|\le |\varepsilon R_{1,d}+R_{2,d}|/(|C_*|\ell^2)$. Lemma~\ref{lem:conditional_expansion_diffusion} therefore justifies a first order expansion inside the drift and gives uniformly for $|\zeta|\le L$,
\begin{equation}
\mathbb{E}_\zeta[g\mathcal A(R)] = \varepsilon^{-2}\mathbb{E}[g_0\mathcal A(R_0)] + \varepsilon^{-1}\left\{ \mathbb{E}[g_{1,d}\mathcal A(R_0)] +\mathbb{E}[g_0R_{1,d}e^{R_0}\mathds1_{\{R_0<0\}}]\right\} +O(1),
\label{eq:accepted_drift_expansion}
\end{equation}
where all remaining products are of smaller order. The first term in \eqref{eq:accepted_drift_expansion} vanishes by equation~\eqref{eq:A_first_moment_disappears}. For the braces term in \eqref{eq:accepted_drift_expansion} we have
\begin{align*}
&\mathbb{E}[g_{1,d}\mathcal A(R_0)] +\mathbb{E}[g_0R_{1,d}e^{R_0}\mathds1_{\{R_0<0\}}]\\
&\quad= -\frac{\ell^2\tau^2}{2\delta\kappa\sigma_{t^*}^2}\,
 \zeta\Biggl\{\mathbb{E}[\mathcal A(R_0)]+C_*\tau\ell^3
 \mathbb{E}\!\left[\left(\xi_1-\frac{C_*\tau\ell^3}{2}\right)e^{R_0}\mathds1_{\{R_0<0\}}\right]\Biggr\}\\
 &\quad=-\frac{\ell^2\tau^2}{2\delta\kappa\sigma_{t^*}^2}\,\zeta
 \left[\left(2+\frac{\sigma_\ell^2}{2}\right)\Phi\!\left(-\frac{\sigma_\ell}{2}\right)
 -\sigma_\ell\phi\!\left(\frac{\sigma_\ell}{2}\right)\right]\\
 &\quad=-\frac{\ell^2\tau^2}{2\delta\kappa\sigma_{t^*}^2}\,\zeta K(\sigma_\ell).
\end{align*}
Here the second equality follows from~\eqref{eq:A_moment_diffusion} and~\eqref{eq:derivative_moment_diffusion}, with $C_*\tau\ell^3 \operatorname{sgn}(C_*) = |C_*|\tau\ell^3=\sigma_\ell$. Using \eqref{eq:delta_zeta}, $d^{1/3}=\varepsilon^{-2}$, and \eqref{eq:h_diffusion} proves \eqref{eq:conditional_drift_diffusion}.
For the second moment, Lemma~\ref{lem:conditional_expansion_diffusion},
the Lipschitz property of $\mathcal A$, and H\"older's inequality give,
\begin{align*}
d^{1/3}\mathbb{E}_\zeta[(\Delta\zeta)^2]
&=\frac{\varepsilon^4}{(\delta\kappa)^2}\mathbb{E}_\zeta[g^2\mathcal A(R)]\\
&=\frac{1}{(\delta\kappa)^2}\mathbb{E}[g_0^2\mathcal A(R_0)]+O(\varepsilon)\\
&=h(\ell)+O(\varepsilon),
\end{align*}
where the final equality follows from \eqref{eq:K_moment_diffusion} and \eqref{eq:h_diffusion}. This proves \eqref{eq:conditional_variance_diffusion}. Finally, the conditional expansion and its moment bounds give, $\mathbb{E}_\zeta[g^4\mathds1_{\Omega_d}]=O(\varepsilon^{-8})$. Using \eqref{eq:delta_zeta}, it follows that
\begin{equation*}
\sup_{|\zeta|\le L} \mathbb{E}_\zeta[(\Delta\zeta)^4\mathds1_{\Omega_d}] \le
\frac{\varepsilon^{12}}{(\delta\kappa)^4} \sup_{|\zeta|\le L}\mathbb{E}_\zeta[g^4\mathds1_{\Omega_d}] =O(\varepsilon^4).
\end{equation*}
The complement is negligible by \eqref{eq:bad_event_increment_bound} and multiplication by $d^{1/3}=\varepsilon^{-2}$ proves \eqref{eq:conditional_fourth_diffusion}.

\label{prop:EK_diffusion_criterion}
Let $c_d\to\infty$ be a positive sequence. For each $d$, let $(Y_k^{(d)})_{k\ge0}$ be a time-homogeneous Markov chain on $\mathds{R}^n$ for fixed $n$. Given $Y_k^{(d)}=x$, write $\Delta_d=Y_{k+1}^{(d)}-Y_k^{(d)}$ and define
\begin{equation}
    \mathsf b_d(x):=c_d\mathbb{E}_x[\Delta_d\mathds1_{\{|\Delta_d|\le1\}}]\,, \quad
    \mathsf a_d(x):=c_d\mathbb{E}_x[\Delta_d\Delta_d^\top \mathds1_{\{|\Delta_d|\le1\}}]\,, \quad
    \mathsf q_d^\eta(x):=c_d\mathbb P_x(|\Delta_d|\ge\eta)\,,
\end{equation}
with $\eta>0$. Assume the following:
\begin{enumerate}
    \item[(i)] for every $R,\eta>0$, the quantities $\mathsf b_d$, $\mathsf a_d$ and $\mathsf q_d^\eta$ converge uniformly on $\{|x|\le R\}$ to $b(x)$, $a(x)$ and zero respectively, where $b:\mathds{R}^n \to \mathds{R}^n$ and $a:\mathds{R}^n \to \mathds{R}^{n \times n}$ are continuous, with $a(x)$ symmetric and nonnegative definite;
    \item[(ii)] the $C([0,\infty),\mathds{R}^n)$ martingale problem for
    \begin{equation*}
        \mathcal LF(x)= \sum_{i=1}^n b_i(x)\partial_i F(x)+\tfrac12 \sum_{i,j=1}^n a_{ij}(x)\partial_{ij} F(x), \qquad F\in C_c^\infty(\mathds{R}^n),
    \end{equation*}
    has a unique solution for every initial law in $\mathcal P(\mathds{R}^n)$;
    \item[(iii)] there exists $\nu\in\mathcal P(\mathds{R}^n)$ such that $Y_0^{(d)}\xrightarrow{\makebox[1em][c]{$\scriptstyled$}}\nu$.
\end{enumerate}
Then, as $d\to\infty$,
\begin{equation*}
\bigl(Y^{(d)}_{\lfloor c_du\rfloor}\bigr)_{u\ge0}\;\Rightarrow\;Y \quad\text{in }D([0,\infty),\mathds{R}^n),
\end{equation*}
where $Y$ solves the martingale problem for $(\mathcal L,\nu)$.
